<?php
function mail_ready():bool{$c=config();return !empty($c['resend_key'])&&!empty($c['email_from']);}
function queue_mail(string $id,array $c,string $kind,string $to,array $payload):void{if(record('mail:'.$id))return;put('mail:'.$id,'mail',['id'=>$id,'case_id'=>$c['id'],'kind'=>$kind,'recipient'=>$to,'mode'=>'live','payload'=>$payload,'status'=>'queued','attempts'=>0,'first_attempt_at'=>null,'next_attempt_at'=>0,'provider_id'=>null,'error'=>null,'created_at'=>now(),'delivered_at'=>null],$c['id']);}
function queue_notice(array $c,string $action,string $id):void{if(!$c['order'])return;$o=$c['order'];$title=['order'=>'Bestätigung Ihres Serviceauftrags / Your service order confirmation','request-information'=>'Rückfrage / More information needed','record-submission'=>'Einreichung dokumentiert / Submission recorded','record-response'=>'Offizielle Antwort verfügbar / Official response available','withdraw'=>'Widerruf eingegangen / Withdrawal received'][$action]??'Aktualisierung / Case update';$p=['subject'=>$title.' · '.$o['reference'],'text'=>$title."\n".$o['reference']."\n\nBitte öffnen Sie Ihren privaten Vorgang. / Please open your private case.\n".config()['public_url'].'/recover-access'];if($action==='order')$p['snapshot']=$c;queue_mail($id,$c,$action,strtolower(trim($c['data']['email'])),$p);}
function access_mail(array $c,string $kind):string{$email=email($c['data']['email']??null);rate($kind.':'.$email,3,3600);$raw=bin2hex(random_bytes(32));$id=uuid();put('token:'.secret_hash($raw),'token',['caseId'=>$c['id'],'email'=>$email,'kind'=>$kind,'expires'=>time()+1800],$c['id'],'',time()+1800);$url=config()['public_url'].($kind==='verify'?'/verify-contact':'/case-access').'#'.$raw;queue_mail($id,$c,$kind,$email,['subject'=>$kind==='verify'?'E-Mail bestätigen / Verify your email':'Privater Zugang / Private access','text'=>($kind==='verify'?'Bestätigen Sie Ihre E-Mail für den Assistenzservice.':'Öffnen Sie Ihren Vorgang. Dieser einmalige Link ersetzt den bisherigen Browserzugang.')."\n\n".$url."\n\n30 Minuten / 30 minutes",'expiresAt'=>time()+1800]);return $id;}
function remote_http(string $url,string $method='GET',?array $payload=null,array $headers=[]):array{
 if(defined('RB_TEST_MAIL_CAPTURE')&&str_starts_with($url,'https://api.resend.com/')){if($payload)file_put_contents(RB_TEST_MAIL_CAPTURE,json_encode($payload,JSON_UNESCAPED_UNICODE)."\n",FILE_APPEND|LOCK_EX);return [200,['id'=>uuid(),'last_event'=>'delivered']];}
 $ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_CONNECTTIMEOUT=>4,CURLOPT_TIMEOUT=>12,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_HTTPHEADER=>$headers]);if($payload!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if($raw===false)throw new RuntimeException('PROVIDER_UNAVAILABLE');return [$code,json_decode($raw,true)??[]];
}
function dispatch_mail(int $limit=5):array{if(!mail_ready())return ['enabled'=>false,'processed'=>0];$processed=0;foreach(array_map(fn($r)=>json_decode($r['data_json'],true),sql("SELECT data_json FROM rb_records WHERE kind='mail' AND JSON_UNQUOTE(JSON_EXTRACT(data_json,'$.status')) IN ('queued','retry','sending') AND CAST(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(data_json,'$.next_attempt_at')), '0') AS UNSIGNED)<=UNIX_TIMESTAMP() AND (JSON_UNQUOTE(JSON_EXTRACT(data_json,'$.status'))<>'sending' OR CAST(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(data_json,'$.lease_until')), '0') AS UNSIGNED)<=UNIX_TIMESTAMP()) ORDER BY created_at,id LIMIT 50")->fetchAll()) as $candidate){if($processed>=$limit)break;db()->beginTransaction();$r=record('mail:'.$candidate['id'],true);if(!$r){db()->commit();continue;}$m=$r['value'];$t=time();if(!in_array($m['status'],['queued','retry','sending'],true)||($m['status']==='sending'&&($m['lease_until']??0)>$t)||$m['next_attempt_at']>$t){db()->commit();continue;}if(($m['payload']['expiresAt']??PHP_INT_MAX)<$t){$m['status']='expired';put('mail:'.$m['id'],'mail',$m,$m['case_id']);db()->commit();continue;}if($m['attempts']>=6||($m['first_attempt_at']!==null&&$t-$m['first_attempt_at']>=23*3600)){$m['status']='needs_review';put('mail:'.$m['id'],'mail',$m,$m['case_id']);db()->commit();continue;}$c=record('case:'.$m['case_id']);if(!$c||$c['owner_hash']==='erasing'||strtolower(trim($c['value']['data']['email']))!==$m['recipient']||(!in_array($m['kind'],['verify','recover'],true)&&(!record('contact:'.$m['case_id'])||record('contact:'.$m['case_id'])['value']['email']!==$m['recipient']))){$m['status']='cancelled';put('mail:'.$m['id'],'mail',$m,$m['case_id']);db()->commit();continue;}$lease=uuid();$m['lease']=$lease;$m['lease_until']=$t+120;$m['status']='sending';$m['attempts']++;$m['first_attempt_at']??=$t;put('mail:'.$m['id'],'mail',$m,$m['case_id']);db()->commit();
 try{$p=$m['payload'];if(isset($p['snapshot'])&&!isset($p['attachments'])){$snapshot=$p['snapshot'];$html=document_html($snapshot);try{$p['attachments']=[['filename'=>$snapshot['order']['reference'].'-confirmation.pdf','content'=>base64_encode(pdf_bytes($html))]];}catch(AppError $e){if($e->reason!=='PDF_USE_HTML')throw $e;$p['attachments']=[['filename'=>$snapshot['order']['reference'].'-contract.html','content'=>base64_encode($html)]];}$o=$snapshot['order'];$amount=number_format(($o['feeCents']??3900)/100,2,',','.');$p['text']="BITTE ÜBERWEISEN SIE {$amount} € / PLEASE TRANSFER €{$amount}\n\nEmpfänger / Recipient: ".$o['beneficiary']."\nIBAN: ".$o['iban']."\nBIC: ".$o['bic']."\nBetrag / Amount: {$amount} €\nVerwendungszweck / Payment reference: ".$o['reference']."\n\nBitte geben Sie unbedingt den Verwendungszweck an. Wir beginnen mit der Bearbeitung, sobald Ihre Zahlung eingegangen ist.\nPlease always enter the payment reference. We start once your payment has arrived.\n\n----\n\n".$p['text'];unset($p['snapshot']);db()->beginTransaction();$check=record('mail:'.$m['id'],true);if(($check['value']['lease']??'')!==$lease)fail('MAIL_LEASE_LOST',409);$m['payload']=$p;put('mail:'.$m['id'],'mail',$m,$m['case_id']);db()->commit();}$send=['from'=>config()['email_from'],'to'=>[$m['recipient']],'subject'=>$p['subject'],'text'=>$p['text']];if(isset($p['attachments']))$send['attachments']=$p['attachments'];[$code,$result]=remote_http('https://api.resend.com/emails','POST',$send,['Authorization: Bearer '.config()['resend_key'],'Content-Type: application/json','Idempotency-Key: rb-php/'.$m['id']]);$status=$code>=200&&$code<300&&!empty($result['id'])?'accepted':($code===429||$code>=500?'retry':'failed');$error=$status==='accepted'?null:'PROVIDER_HTTP_'.$code;$provider=$result['id']??null;}catch(Throwable){if(db()->inTransaction())db()->rollBack();$status='retry';$error='DELIVERY_UNCERTAIN';$provider=null;}
 db()->beginTransaction();$check=record('mail:'.$m['id'],true);if($check&&($check['value']['lease']??'')===$lease){$m=$check['value'];$m['status']=$status;$m['error']=$error;$m['provider_id']=$provider;$m['next_attempt_at']=$t+min(3600,60*(2**$m['attempts']));unset($m['lease'],$m['lease_until']);put('mail:'.$m['id'],'mail',$m,$m['case_id']);}db()->commit();$processed++;}return ['enabled'=>true,'processed'=>$processed];}
function refresh_delivery(string $id):array{$r=record('mail:'.$id,true);if(!$r)fail('DOCUMENT_NOT_FOUND',404);$m=$r['value'];if($m['provider_id']){[$code,$status]=remote_http('https://api.resend.com/emails/'.rawurlencode($m['provider_id']),'GET',null,['Authorization: Bearer '.config()['resend_key']]);if($code===200&&in_array($status['last_event']??'',['delivered','bounced','complained'],true)){$m['status']=$status['last_event'];if($m['status']==='delivered')$m['delivered_at']=now();put('mail:'.$id,'mail',$m,$m['case_id']);}}return ['mail'=>public_mail($m)];}
function public_mail(array $m):array{unset($m['payload'],$m['lease'],$m['lease_until']);return $m;}
